1	#!/usr/bin/env node
2	// config-to-document — consultant notes (written by the module consultant agent,
3	// reviewed by a second agent) for the IMG activities of a snapshot.
4	//
5	//   node scripts/config/notes.mjs scopes --module MM [--size 12]
6	//        → activities and batches per scope (custom | values | all), reviewed ones left out
7	//   node scripts/config/notes.mjs batches --module MM [--scope custom|values|all] [--size 12] [--redo]
8	//        → notes/_in/bNNN.json per batch (activity context for the writer) + manifest on stdout
9	//   node scripts/config/notes.mjs save --module MM --batch b001 --kind draft|review|revised  < text
10	//        → notes/b001.<kind>.json (text in the marker format below, parsed and validated)
11	//   node scripts/config/notes.mjs terms --module MM
12	//        → terms/_in/tNNN.json: names without a document-language text (150 per batch);
13	//          save with --batch tNNN --kind draft|review, lines `tNNN-NNN = <translation>`
14	//   node scripts/config/notes.mjs status --module MM
15	//
16	// Marker format (draft / revised):        Marker format (review):
17	//   @@ <IMG activity id>                    @@ <IMG activity id>
18	//   ## purpose                              verdict: ok | fix
19	//   <one or two sentences>                  - <what is wrong, what the data says>
20	//   ## impact
21	//   - <bullet>            (also: ## cautions, ## refs)
22	
23	import { readFileSync, existsSync, readdirSync } from 'fs';
24	import { join, resolve, dirname } from 'path';
25	import { fileURLToPath } from 'url';
26	import { resolveArtifactBase, sc4sapHome } from '../lib/profile-resolve.mjs';
27	import { atomicWriteFileSync, ensureDirSync } from '../lib/atomic-write.mjs';
28	import { buildModel } from './build-config-doc.mjs';
29	import { loadRules, runChecks, attachActivities } from './config-checks.mjs';
30	
31	const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..');
32	const CONTEXT_ROWS = 15;
33	
34	function opts(argv) {
35	  const o = { cmd: argv[0], module: '', scope: 'custom', size: 12, batch: '', kind: '', redo: false, file: '' };
36	  for (let i = 1; i < argv.length; i++) {
37	    const a = argv[i];
38	    if (a === '--module') o.module = String(argv[++i]).toUpperCase();
39	    else if (a === '--scope') o.scope = argv[++i];
40	    else if (a === '--size') o.size = Math.max(1, Number(argv[++i]) || 12);
41	    else if (a === '--batch') o.batch = argv[++i];
42	    else if (a === '--kind') o.kind = argv[++i];
43	    else if (a === '--redo') o.redo = true;
44	    else if (a === '--file') o.file = argv[++i];
45	  }
46	  if (!o.module) throw new Error('--module is required');
47	  return o;
48	}
49	
50	const dirOf = (module) => join(resolveArtifactBase(process.cwd()), 'config-docs', module);
51	
52	// Sources of the reference panel: official SAP documentation only — SAP Help
53	// Portal, SAP Notes / KBAs, SAP Learning. Anything else is refused on save and
54	// dropped by the builder.
55	const OFFICIAL_HOSTS = ['help.sap.com', 'me.sap.com', 'launchpad.support.sap.com', 'userapps.support.sap.com', 'support.sap.com', 'learning.sap.com'];
56	export function isOfficialSource(url) {
57	  try {
58	    const u = new URL(String(url));
59	    return u.protocol === 'https:' && OFFICIAL_HOSTS.includes(u.hostname.toLowerCase());
60	  } catch {
61	    return false;
62	  }
63	}
64	
65	const bullet = (l) => l.replace(/^\s*[-*]\s+/, '').trim();
66	const kv = (l) => /^\s*([a-z0-9]+)\s*:\s*(.*)$/i.exec(l);
67	
68	/** One activity's note: the notes card (purpose … refs) and the reference panel (sapdoc … sources). */
69	function parseNote(body) {
70	  const note = { purpose: '', impact: [], cautions: [], refs: [], sapdoc: '', cases: null, mix: '', compare: [], checklist: [], criteria: {}, sources: [], verdicts: [] };
71	  let sec = null;
72	  let kase = null;
73	  for (const raw of body.split('\n')) {
74	    const line = raw.trimEnd();
75	    const sub = /^###\s*case\b\s*(.*)$/i.exec(line);
76	    if (sub && sec === 'cases') { kase = { title: sub[1].trim(), flow: [], desc: '', when: '', thisSystem: '' }; note.cases.list.push(kase); continue; }
77	    const h = /^##\s*(\w+)\s*(.*)$/.exec(line);
78	    if (h) {
79	      sec = h[1].toLowerCase();
80	      kase = null;
81	      if (sec === 'cases') note.cases = { title: h[2].trim(), list: [] };
82	      continue;
83	    }
84	    if (!sec || !line.trim()) continue;
85	    if (sec === 'purpose' || sec === 'sapdoc' || sec === 'mix') note[sec] = `${note[sec]} ${line.trim()}`.trim();
86	    else if (['impact', 'cautions', 'refs', 'checklist'].includes(sec)) note[sec].push(bullet(line));
87	    else if (sec === 'cases' && kase) {
88	      const m = kv(line);
89	      if (m && m[1].toLowerCase() === 'flow') kase.flow = m[2].split('>').map((s) => s.trim()).filter(Boolean);
90	      else if (m && ['desc', 'when'].includes(m[1].toLowerCase())) kase[m[1].toLowerCase()] = m[2].trim();
91	      else if (m && m[1].toLowerCase() === 'this') kase.thisSystem = m[2].trim();
92	      else kase.desc = `${kase.desc} ${line.trim()}`.trim();
93	    } else if (sec === 'compare' && line.includes('|')) {
94	      const cells = line.replace(/^\s*\|/, '').replace(/\|\s*$/, '').split('|').map((s) => s.trim());
95	      if (!cells.every((c) => /^:?-{2,}:?$/.test(c))) note.compare.push(cells);
96	    } else if (sec === 'criteria') {
97	      const m = kv(line);
98	      if (m) note.criteria[m[1].toLowerCase()] = m[2].trim();
99	    } else if (sec === 'verdicts') {
100	      // System-only notes (general part from the knowledge base): `CASE 2: yes — <evidence>`.
101	      const m = /^\s*-?\s*CASE\s*(\d+)\s*:\s*(.+)$/i.exec(line);
102	      if (m) note.verdicts.push({ n: Number(m[1]), value: m[2].trim() });
103	    } else if (sec === 'sources') {
104	      const [title = '', source = '', url = '', summary = ''] = bullet(line).split('|').map((s) => s.trim());
105	      if (title) note.sources.push({ title, source, url, summary });
106	    }
107	  }
108	  return note;
109	}
110	
111	/** Parse the marker text; returns { items: {id: {...}}, errors: [] }. */
112	export function parseNotes(text, kind) {
113	  const items = {};
114	  const errors = [];
115	  for (const chunk of String(text).replace(/\r\n/g, '\n').split(/^@@\s*/m).slice(1)) {
116	    const [head, ...rest] = chunk.split('\n');
117	    const id = head.trim();
118	    if (!id) continue;
119	    const body = rest.join('\n');
120	    if (kind === 'review') {
121	      const verdict = /^verdict:\s*(ok|fix)\b/im.exec(body)?.[1]?.toLowerCase();
122	      if (!verdict) errors.push(`${id}: no "verdict: ok|fix" line`);
123	      items[id] = { verdict: verdict || 'fix', issues: body.split('\n').filter((l) => /^\s*-\s+/.test(l)).map((l) => l.replace(/^\s*-\s+/, '').trim()) };
124	      continue;
125	    }
126	    items[id] = parseNote(body);
127	    if (!items[id].purpose) errors.push(`${id}: empty purpose`);
128	    for (const s of items[id].sources.filter((x) => !isOfficialSource(x.url))) errors.push(`${id}: source not official SAP documentation (${s.url || s.title}) — use help.sap.com, SAP Notes/KBAs or learning.sap.com`);
129	  }
130	  return { items, errors };
131	}
132	
133	// Sample rows for the writer: customer rows first, codes with their fixed-value text.
134	function rowsFor(v, domains) {
135	  const order = [...v.cust, ...v.rows.map((_, i) => i).filter((i) => !v.cust.includes(i))].slice(0, CONTEXT_ROWS);
136	  // Two columns may share a label (plant / plant name): name them by field then.
137	  const seen = v.cols.reduce((m, c) => m.set(c.label, (m.get(c.label) || 0) + 1), new Map());
138	  const names = v.cols.map((c) => (seen.get(c.label) > 1 ? `${c.label} [${c.name}]` : c.label));
139	  return order.map((i) => Object.fromEntries(v.cols.map((c, j) => {
140	    const x = v.rows[i][j];
141	    const tx = c.dom && domains[c.dom]?.[x];
142	    return [names[j], tx ? `${x} (${tx})` : x];
143	  }).filter(([, x]) => x !== '')));
144	}
145	
146	function batches(o) {
147	  const dir = dirOf(o.module);
148	  const snap = JSON.parse(readFileSync(join(dir, 'snapshot.json'), 'utf8'));
149	  const lang = snap.meta.lang || 'ko';
150	  snap.__theme = undefined;
151	  const { views, acts } = buildModel(snap, lang, { drawScreens: false });
152	  const rules = loadRules(join(ROOT, 'configs', o.module, 'config-checks.json'));
153	  const checks = attachActivities(runChecks(snap, rules, (a) => (acts[a.id] ? acts[a.id].viewKeys.map((k) => ({ tables: [views[k].root] })) : []), lang), rules, acts)
154	    .filter((c) => c.items.length);
155	  const paths = {};
156	  const order = [];
157	  const walk = (nodes, path) => nodes.forEach((n) => (n.kind === 'activity' ? (paths[n.activity] = path, order.push(n.activity)) : walk(n.children || [], n.text ? [...path, n.text] : path)));
158	  walk(snap.tree, []);
159	  const SCOPES = { custom: ['custom'], values: ['custom', 'standard', 'empty'], all: null };
160	  // Activities that already have reviewed notes are skipped unless --redo.
161	  const done = new Set(Object.entries(loadNotes(dir)).filter(([, n]) => !o.redo && ['ok', 'revised'].includes(n.review)).map(([id]) => id));
162	  const pick = (scope) => [...new Set(order)].filter((id) => acts[id] && !done.has(id) && (!SCOPES[scope] || SCOPES[scope].includes(acts[id].status)));
163	  if (o.cmd === 'scopes') {
164	    const out = Object.fromEntries(Object.keys(SCOPES).map((s) => [s, { activities: pick(s).length, batches: Math.ceil(pick(s).length / o.size) }]));
165	    process.stdout.write(JSON.stringify({ size: o.size, alreadyReviewed: done.size, ...out }, null, 1) + '\n');
166	    return;
167	  }
168	  if (!(o.scope in SCOPES)) throw new Error('--scope custom | values | all');
169	  // Activities already in a batch input (written, under review or waiting) are not batched again.
170	  const batched = new Set(existsSync(join(dir, 'notes', '_in')) ? readdirSync(join(dir, 'notes', '_in')).filter((f) => /^b\d{3}\.json$/.test(f))
171	    .flatMap((f) => JSON.parse(readFileSync(join(dir, 'notes', '_in', f), 'utf8')).items.map((x) => x.id)) : []);
172	  const ids = pick(o.scope).filter((id) => o.redo || !batched.has(id));
173	  const docText = (id) => (snap.docs[acts[id].docuId]?.blocks || []).map((b) => b.text).join(' ').slice(0, 1000);
174	  // Activities whose general part (purpose, SAP documentation, cases, criteria,
175	  // sources) is already in the knowledge base get only the system part written.
176	  const kb = (id) => kbRead(o.module, lang, id);
177	  const inDir = join(dir, 'notes', '_in');
178	  ensureDirSync(inDir);
179	  const manifest = [];
180	  // New batches are numbered after every existing batch input, so no batch — written,
181	  // in progress or waiting — is ever overwritten.
182	  const first = Math.max(0, ...readdirSync(inDir).map((f) => Number(/^b(\d{3})\.json$/.exec(f)?.[1] || 0)));
183	  for (let i = 0; i < ids.length; i += o.size) {
184	    const name = `b${String(first + i / o.size + 1).padStart(3, '0')}`;
185	    const items = ids.slice(i, i + o.size).map((id) => {
186	      const a = acts[id];
187	      return {
188	        id, path: paths[id], title: a.title, titleEn: a.titleEn, tcode: a.tcode, status: a.status,
189	        objects: a.viewKeys.map((k) => ({ key: k, title: views[k].title, table: views[k].root, rows: views[k].rows.length, customerRows: views[k].cust.length, columns: views[k].cols.map((c) => `${c.label} [${c.name}]`), sample: rowsFor(views[k], snap.domains || {}) })),
190	        checks: checks.filter((c) => c.activities.includes(id)).map((c) => ({ severity: c.severity, title: c.title, items: c.items.slice(0, 10) })),
191	        ...(kb(id)
192	          ? { mode: 'system', kb: { purpose: kb(id).purpose, cases: (kb(id).cases?.list || []).map((c, n) => `CASE ${n + 1}: ${c.title} — ${c.desc}`) } }
193	          : { mode: 'full', sapDoc: docText(id) }),
194	      };
195	    });
196	    atomicWriteFileSync(join(inDir, `${name}.json`), JSON.stringify({ module: o.module, system: snap.meta.system, lang, items }, null, 1));
197	    manifest.push({ batch: name, file: join(inDir, `${name}.json`), activities: items.length });
198	  }
199	  process.stdout.write(JSON.stringify({ scope: o.scope, activities: ids.length, batches: manifest }, null, 1) + '\n');
200	}
201	
202	function saveTerms(o) {
203	  if (!['draft', 'review'].includes(o.kind)) throw new Error('term batches take --kind draft|review');
204	  const dir = join(dirOf(o.module), 'terms');
205	  const input = JSON.parse(readFileSync(join(dir, '_in', `${o.batch}.json`), 'utf8'));
206	  const known = new Set(input.items.map((x) => x.id));
207	  const items = parseTerms(readFileSync(o.file || 0, 'utf8'));
208	  const errors = Object.keys(items).filter((id) => !known.has(id)).map((id) => `${id}: not in batch ${o.batch}`);
209	  for (const id of Object.keys(items)) if (!known.has(id)) delete items[id];
210	  if (o.kind === 'draft') for (const id of known) if (!items[id]) errors.push(`${id}: missing`);
211	  atomicWriteFileSync(join(dir, `${o.batch}.${o.kind}.json`), JSON.stringify({ batch: o.batch, kind: o.kind, savedAt: new Date().toISOString(), items }, null, 1));
212	  process.stdout.write(JSON.stringify({ ok: errors.length === 0, saved: Object.keys(items).length, errors }) + '\n');
213	}
214	
215	function save(o) {
216	  if (/^t\d{3}$/.test(o.batch)) return saveTerms(o);
217	  if (!/^b\d{3}$/.test(o.batch) || !['draft', 'review', 'revised'].includes(o.kind)) throw new Error('--batch bNNN and --kind draft|review|revised are required');
218	  const dir = join(dirOf(o.module), 'notes');
219	  const input = JSON.parse(readFileSync(join(dir, '_in', `${o.batch}.json`), 'utf8'));
220	  const known = new Set(input.items.map((x) => x.id));
221	  const parsed = parseNotes(readFileSync(o.file || 0, 'utf8'), o.kind);
222	  const { items } = parsed;
223	  // System-only items (general part in the knowledge base) need no purpose, but a verdict per KB case.
224	  const systemOnly = new Map(input.items.filter((x) => x.mode === 'system').map((x) => [x.id, x.kb.cases.length]));
225	  const errors = parsed.errors.filter((e) => !(systemOnly.has(e.split(':')[0]) && /empty purpose/.test(e)));
226	  if (o.kind !== 'review') {
227	    for (const [id, n] of systemOnly) if (items[id] && items[id].verdicts.length < n && !items[id].cases) errors.push(`${id}: needs a "## verdicts" line for each of its ${n} cases`);
228	  }
229	  for (const id of Object.keys(items)) if (!known.has(id)) { errors.push(`${id}: not in batch ${o.batch}`); delete items[id]; }
230	  if (o.kind !== 'revised') for (const id of known) if (!items[id]) errors.push(`${id}: missing`);
231	  // Revisions accumulate: a later follow-up revision replaces only the items it carries.
232	  const out = join(dir, `${o.batch}.${o.kind}.json`);
233	  const kept = o.kind === 'revised' && existsSync(out) ? JSON.parse(readFileSync(out, 'utf8')).items : {};
234	  atomicWriteFileSync(out, JSON.stringify({ batch: o.batch, kind: o.kind, savedAt: new Date().toISOString(), items: { ...kept, ...items } }, null, 1));
235	  const fix = o.kind === 'review' ? Object.entries(items).filter(([, r]) => r.verdict === 'fix').map(([id]) => id) : [];
236	  process.stdout.write(JSON.stringify({ ok: errors.length === 0, saved: Object.keys(items).length, errors, ...(o.kind === 'review' ? { fix } : {}) }) + '\n');
237	}
238	
239	// ── terms: names SAP has no document-language text for (IMG folders, activity
240	// titles, field labels), translated by the consultant agent and corrected by the
241	// reviewer. Marker format: one line per term, `t0001 = <translation>`; the review
242	// lists corrections only: `t0001 = <corrected> | <reason>`.
243	const hasKo = (t) => /[가-힣]/.test(String(t || ''));
244	
245	function termSources(snap) {
246	  const out = [];
247	  // Labels carry their data element and long text, so an abbreviation is not guessed.
248	  const add = (kind, en, ctx = {}) => { if (en && !hasKo(en) && /[A-Za-z]/.test(en)) out.push({ kind, en, ...ctx }); };
249	  const walk = (nodes) => nodes.forEach((n) => (n.kind === 'folder' ? (add('folder', n.text || n.textEn), walk(n.children || [])) : null));
250	  walk(snap.tree);
251	  for (const a of Object.values(snap.activities)) add('activity', a.title || a.titleEn);
252	  const used = new Set(Object.values(snap.tables).flatMap((t) => (t.fields || []).map((f) => f.rollname)));
253	  for (const [r, l] of Object.entries(snap.labels)) if (used.has(r)) add('label', l.m || l.s || l.l || l.h || l.d, { dataElement: r, longText: l.d || l.l || '' });
254	  const seen = new Set();
255	  return out.filter((x) => !seen.has(`${x.kind}|${x.en}`) && seen.add(`${x.kind}|${x.en}`));
256	}
257	
258	function terms(o) {
259	  const dir = dirOf(o.module);
260	  const snap = JSON.parse(readFileSync(join(dir, 'snapshot.json'), 'utf8'));
261	  const known = loadTerms(dir);
262	  const todo = termSources(snap).filter((x) => !known[x.kind]?.[x.en]);
263	  const tdir = join(dir, 'terms', '_in');
264	  ensureDirSync(tdir);
265	  const first = Math.max(0, ...readdirSync(tdir).map((f) => Number(/^t(\d{3})\.json$/.exec(f)?.[1] || 0)));
266	  const size = 150;
267	  const manifest = [];
268	  for (let i = 0; i < todo.length; i += size) {
269	    const name = `t${String(first + i / size + 1).padStart(3, '0')}`;
270	    const items = todo.slice(i, i + size).map((x, j) => ({ id: `${name}-${String(j + 1).padStart(3, '0')}`, ...x }));
271	    atomicWriteFileSync(join(tdir, `${name}.json`), JSON.stringify({ module: o.module, lang: snap.meta.lang || 'ko', items }, null, 1));
272	    manifest.push({ batch: name, file: join(tdir, `${name}.json`), terms: items.length });
273	  }
274	  process.stdout.write(JSON.stringify({ terms: todo.length, batches: manifest }, null, 1) + '\n');
275	}
276	
277	export function parseTerms(text) {
278	  const out = {};
279	  for (const line of String(text).replace(/\r\n/g, '\n').split('\n')) {
280	    const m = /^\s*(t\d{3}-\d{3})\s*=\s*(.+?)\s*$/.exec(line);
281	    if (m) out[m[1]] = m[2].split('|')[0].trim();
282	  }
283	  return out;
284	}
285	
286	/** { folder: {en: ko}, activity: {…}, label: {…} } — reviewer corrections win over drafts. */
287	export function loadTerms(dir) {
288	  const tdir = join(dir, 'terms');
289	  const out = { folder: {}, activity: {}, label: {} };
290	  if (!existsSync(join(tdir, '_in'))) return out;
291	  for (const f of readdirSync(join(tdir, '_in')).filter((x) => /^t\d{3}\.json$/.test(x))) {
292	    const b = f.slice(0, 4);
293	    const read = (k) => (existsSync(join(tdir, `${b}.${k}.json`)) ? JSON.parse(readFileSync(join(tdir, `${b}.${k}.json`), 'utf8')).items : {});
294	    const draft = read('draft'), review = read('review');
295	    for (const it of JSON.parse(readFileSync(join(tdir, '_in', f), 'utf8')).items) {
296	      const ko = review[it.id] || draft[it.id];
297	      if (ko) out[it.kind][it.en] = ko; // also terms kept in English, so they are not asked again
298	    }
299	  }
300	  return out;
301	}
302	
303	// ── knowledge base: the system-independent part of reviewed notes, per module,
304	// language and IMG activity, under ~/.sc4sap/kb/config/ — reused by every later
305	// run and every other system, so only the system part is written again.
306	const GENERAL = ['purpose', 'sapdoc', 'mix', 'compare', 'checklist', 'criteria'];
307	const kbDir = (module, lang) => join(sc4sapHome(), 'kb', 'config', module, lang);
308	const kbFile = (module, lang, id) => join(kbDir(module, lang), `${id.replace(/[^A-Za-z0-9_-]/g, '_')}.json`);
309	export function kbRead(module, lang, id) {
310	  const f = kbFile(module, lang, id);
311	  return existsSync(f) ? JSON.parse(readFileSync(f, 'utf8')) : null;
312	}
313	
314	/** General part of one reviewed note (case verdicts are system-specific and left out). */
315	export function generalPart(note) {
316	  const out = Object.fromEntries(GENERAL.map((k) => [k, note[k]]));
317	  out.cases = note.cases ? { title: note.cases.title, list: note.cases.list.map(({ thisSystem, svg, ...c }) => c) } : null;
318	  out.sources = (note.sources || []).filter((s) => isOfficialSource(s.url));
319	  return out;
320	}
321	
322	/** Note + knowledge base: general fields filled from the KB, verdicts applied to its cases. */
323	export function withKb(note, entry) {
324	  if (!entry) return note;
325	  const out = { ...note };
326	  for (const k of GENERAL) if (!out[k] || (Array.isArray(out[k]) && !out[k].length) || (typeof out[k] === 'object' && !Array.isArray(out[k]) && !Object.keys(out[k]).length)) out[k] = entry[k];
327	  if (!out.sources?.length) out.sources = (entry.sources || []).map((s) => ({ ...s, fromKb: true }));
328	  if (!out.cases && entry.cases) {
329	    out.cases = { title: entry.cases.title, list: entry.cases.list.map((c, n) => ({ ...c, thisSystem: (note.verdicts || []).find((v) => v.n === n + 1)?.value || '' })) };
330	  }
331	  return out;
332	}
333	
334	function kbPromote(o) {
335	  const dir = dirOf(o.module);
336	  const lang = JSON.parse(readFileSync(join(dir, 'snapshot.json'), 'utf8')).meta.lang || 'ko';
337	  ensureDirSync(kbDir(o.module, lang));
338	  let saved = 0, kept = 0;
339	  for (const [id, n] of Object.entries(loadNotes(dir))) {
340	    if (!['ok', 'revised'].includes(n.review) || !n.cases || n.fromKb) continue;
341	    if (!o.redo && kbRead(o.module, lang, id)) { kept++; continue; }
342	    atomicWriteFileSync(kbFile(o.module, lang, id), JSON.stringify({ activity: id, module: o.module, lang, savedAt: new Date().toISOString(), ...generalPart(n) }, null, 1));
343	    saved++;
344	  }
345	  process.stdout.write(JSON.stringify({ kb: kbDir(o.module, lang), saved, kept }) + '\n');
346	}
347	
348	/** Merge drafts, reviews and revisions: { id: { ...note, review: 'ok'|'revised'|'open'|'none', issues } }. */
349	export function loadNotes(dir, { module = '', lang = 'ko' } = {}) {
350	  const ndir = join(dir, 'notes');
351	  if (!existsSync(ndir)) return {};
352	  const read = (f) => (existsSync(join(ndir, f)) ? JSON.parse(readFileSync(join(ndir, f), 'utf8')).items : {});
353	  const out = {};
354	  for (const b of readdirSync(ndir).filter((f) => /^b\d{3}\.draft\.json$/.test(f)).map((f) => f.slice(0, 4))) {
355	    const draft = read(`${b}.draft.json`), review = read(`${b}.review.json`), revised = read(`${b}.revised.json`);
356	    for (const [id, note] of Object.entries(draft)) {
357	      const r = review[id];
358	      const fixed = revised[id];
359	      const n = fixed || note;
360	      const m = module ? withKb(n, kbRead(module, lang, id)) : n;
361	      out[id] = { ...m, sources: (m.sources || []).filter((s) => isOfficialSource(s.url)), review: fixed ? 'revised' : r ? (r.verdict === 'ok' ? 'ok' : 'open') : 'none', issues: fixed ? [] : r?.issues || [] };
362	    }
363	  }
364	  return out;
365	}
366	
367	function status(o) {
368	  const ndir = join(dirOf(o.module), 'notes');
369	  const ins = existsSync(join(ndir, '_in')) ? readdirSync(join(ndir, '_in')).filter((f) => f.endsWith('.json')).map((f) => f.slice(0, 4)) : [];
370	  const has = (b, k) => existsSync(join(ndir, `${b}.${k}.json`));
371	  process.stdout.write(JSON.stringify(ins.map((b) => ({ batch: b, draft: has(b, 'draft'), review: has(b, 'review'), revised: has(b, 'revised') })), null, 1) + '\n');
372	}
373	
374	if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
375	  try {
376	    const o = opts(process.argv.slice(2));
377	    const run = { batches, scopes: batches, terms, kb: kbPromote, save, status }[o.cmd];
378	    if (!run) throw new Error('command: scopes | batches | terms | kb | save | status');
379	    run(o);
380	  } catch (e) {
381	    process.stderr.write(`[notes] ${e.message}\n`);
382	    process.exit(1);
383	  }
384	}
385

