221	if(n.sources&&n.sources.length)h+='<h4>'+esc(T.sources)+'</h4>'+n.sources.map(s=>'<div class="rf"><b>'+esc(s.title)+'</b><div class="src">'+esc(s.source)+'</div>'+(s.summary?'<p>'+esc(s.summary)+'</p>':'')+(/^https?:\/\//.test(s.url)?'<a href="'+esc(s.url)+'" target="_blank" rel="noopener noreferrer">'+esc(s.url)+'</a>':'')+'</div>').join('');
222	return h}
223	function renderRef(){const tabs='<div class="tabs"><button data-tab="ref" aria-pressed="'+(refTab==='ref')+'">'+esc(T.refPanel)+'</button><button data-tab="chk" aria-pressed="'+(refTab==='chk')+'">'+esc(T.ref)+' '+found.length+'</button></div>';$('#ref').innerHTML=tabs+(refTab==='chk'||!cur?checklistHtml():refHtml(cur))}
224	const route=()=>{const m=/act=([^&]+)/.exec(location.hash);m?show(decodeURIComponent(m[1])):home()};window.addEventListener('hashchange',route);route();
225	})();
226	`;
227	
228	const packed = (v) => gzipSync(Buffer.from(JSON.stringify(v), 'utf8'), { level: 9 }).toString('base64');
229	
230	export function pageHtml(data, svgs) {
231	  const T = TEXT[data.lang] || TEXT.en;
232	  const clientT = Object.fromEntries(Object.entries(T).map(([k, v]) => [k, typeof v === 'function' ? undefined : v]).filter(([, v]) => v !== undefined));
233	  const title = T.title(data.meta.module);
234	  const fn = `T.title=${T.title.toString()};T.truncated=${T.truncated.toString()};T.lead=${T.lead.toString()};T.checked=${T.checked.toString()};T.found=${T.found.toString()};T.more=${T.more.toString()};T.showAll=${T.showAll.toString()};`;
235	  const chips = ['all', 'custom', 'standard', 'empty', 'none', 'blocked', 'checks', 'notes']
236	    .map((f) => `<button class="chip" data-f="${f}" aria-pressed="${f === 'all'}">${['all', 'checks', 'notes'].includes(f) ? '' : `<i class="s-${f}"></i>`}${f === 'notes' ? `📎 ${T.refPanel}` : T[f]}</button>`).join('');
237	  return `<!doctype html>
238	<html lang="${data.lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
239	<title>${title} · ${data.meta.system}</title><style>${CSS}</style></head>
240	<body>
241	<header><button id="menubtn">☰</button><h1>${title}</h1><span class="sub">${T.lead(data.meta)}</span><button id="refbtn">${T.refPanel}</button></header>
242	<div class="wrap">
243	<aside><div class="search"><input id="q" type="search" placeholder="${T.search}"><div class="chips">${chips}</div><div class="count" id="count"></div></div>
244	<div class="tools"><button id="expall">${T.expand}</button><button id="colall">${T.collapse}</button><button id="home">${T.home}</button></div>
245	<div id="tree"></div></aside>
246	<main id="main"></main>
247	<section id="ref"></section>
248	</div>
249	<div class="lb" id="lb"><div></div></div>
250	<script type="application/octet-stream" id="data">${packed({ ...data, T: clientT })}</script>
251	<script type="application/octet-stream" id="svgs">${packed(svgs)}</script>
252	<script>${SCRIPT.replace('const T=D.T;', `const T=D.T;${fn}`)}</script>
253	</body></html>
254	`;
255	}
256

