    edit: 'Edit', done: 'Done', save: 'Save', undo: 'Undo', add: '+ Add item', del: 'Delete', newNote: '+ Add notes',
    edited: 'Edited', draft: 'You have unsaved edits', resume: 'Continue editing', discard: 'Discard', unsaved: 'You have unsaved changes.',
