node - <<'EOF'
const fs=require('fs');const f='config-doc-page.mjs';let s=fs.readFileSync(f,'utf8');
const rep=(a,b)=>{if(!s.includes(a))throw new Error('missing: '+a.slice(0,60));s=s.replace(a,()=>b)};
rep(`const STATUS=['custom','standard','empty','none','blocked'];`,`const STATUS=['custom','standard','empty','none','blocked'];\n/*EDITOR*/`);
rep(`import { gzipSync } from 'zlib';`,`import { gzipSync } from 'zlib';\nimport { EDITOR_SCRIPT, EDITOR_STYLE, editorLabels } from './config-doc-editor.mjs';`);
rep("<title>${title} · ${data.meta.system}</title><style>${CSS}</style></head>","<title>${title} · ${data.meta.system}</title><style>${CSS}${EDITOR_STYLE}</style></head>");
rep('<button id="refbtn">${T.refPanel}</button></header>','<button id="refbtn">${T.refPanel}</button><button id="ce-undo">${EL.undo}</button><button id="ce-save">${EL.save}</button><button id="ce-edit">${EL.edit}</button></header>');
rep('<script type="application/octet-stream" id="data">${packed({ ...data, T: clientT })}</script>','<script type="application/octet-stream" id="data">${packed({ ...data, edits: undefined, T: clientT, EL })}</script>\n<script type="application/json" id="config-edits">${JSON.stringify(data.edits || {}).replace(/</g, \'\\\\u003c\')}</script>');
rep("<script>${SCRIPT.replace('const T=D.T;', `const T=D.T;${fn}`)}</script>","<script>${SCRIPT.replace('const T=D.T;', `const T=D.T;${fn}`).replace('/*EDITOR*/', () => EDITOR_SCRIPT)}</script>");
rep("  const title = T.title(data.meta.module);","  const EL = editorLabels(data.lang);\n  const title = T.title(data.meta.module);");
fs.writeFileSync(f,s);console.log('ok');
EOF
