// Static server for the edit-mode test page (localhost only).
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { join, normalize } from 'node:path';
const root = join(import.meta.dirname, 'edit-test');
createServer(async (req, res) => {
  const p = normalize(join(root, decodeURIComponent(new URL(req.url, 'http://x').pathname)));
  if (!p.startsWith(root)) { res.writeHead(403).end(); return; }
  try { const b = await readFile(p); res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' }).end(b); }
  catch { res.writeHead(404).end(); }
}).listen(8765, '127.0.0.1', () => console.log('http://127.0.0.1:8765/'));

