// Makes a page as edit mode would save it: one edited note embedded in #config-edits.
import { readFileSync, writeFileSync } from 'node:fs';
import { gunzipSync } from 'node:zlib';
const [src, out] = process.argv.slice(2);
const html = readFileSync(src, 'utf8');
const data = JSON.parse(gunzipSync(Buffer.from(/id="data">([^<]+)</.exec(html)[1], 'base64')).toString('utf8'));
const id = 'OLMEOMGS_3';
const note = structuredClone(data.notes[id]);
note.purpose = '테스트 목적 수정 <b>태그</b>';
note.impact.push('새 영향 항목');
note.edited = { author: 'tester', at: '2026-10-15T09:00:00.000Z' };
const ce = { edits: { [id]: note }, log: [{ author: 'tester', at: '2026-10-15T09:00:00.000Z', note: 'test', activities: [id] }], system: data.meta.system, module: data.meta.module };
const tag = /<script type="application\/json" id="config-edits">[\s\S]*?<\/script>/;
writeFileSync(out, html.replace(tag, () => `<script type="application/json" id="config-edits">${JSON.stringify(ce).replace(/</g, '\\u003c')}</script>`));
console.log('written', out);

