// Draws every screen and case diagram of the MM document into gallery pages
// (300 drawings each) with an audit script that finds overlapping texts.
// Usage: node gen.mjs <workspace root> <out dir>
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const [ws, out] = process.argv.slice(2);
const src = (p) => 'file:///' + join(ws, 'sc4sap', p).replace(/\\/g, '/');
const { buildModel, applyTerms } = await import(src('scripts/config/build-config-doc.mjs'));
const { loadNotes, loadTerms } = await import(src('scripts/config/notes.mjs'));
const { renderProcessFlowHorizontalSVG } = await import(src('scripts/spec/screen-image-renderer.mjs'));
const { readScreenTheme } = await import(src('scripts/lib/profile-resolve.mjs'));
const dir = join(ws, '.sc4sap/work/HKT-DEV/config-docs/MM');
const snap = JSON.parse(readFileSync(join(dir, 'snapshot.json'), 'utf8'));
applyTerms(snap, loadTerms(dir));
snap.__theme = readScreenTheme(ws) ?? undefined;
const { svgs } = buildModel(snap, 'ko');
const all = Object.entries(svgs);
for (const [id, n] of Object.entries(loadNotes(dir))) {
  (n.cases?.list || []).forEach((c, i) => { if (c.flow?.length) all.push([`case:${id}:${i}`, renderProcessFlowHorizontalSVG(c.flow, { lang: 'ko' })]); });
}
mkdirSync(out, { recursive: true });
const AUDIT = `
<script>
// Two texts overlap when their boxes intersect by more than 1.5 px both ways.
window.audit=()=>{const res=[];for(const fig of document.querySelectorAll('figure')){const ts=[...fig.querySelectorAll('text')].filter(t=>t.textContent.trim());const bs=ts.map(t=>t.getBoundingClientRect());const root=fig.querySelector('svg').getBoundingClientRect();
for(let i=0;i<ts.length;i++){const a=bs[i];if(a.right>root.right+1||a.left<root.left-1)res.push({k:fig.dataset.k,kind:'outside',t:ts[i].textContent.slice(0,40)});
for(let j=i+1;j<ts.length;j++){const b=bs[j];const ox=Math.min(a.right,b.right)-Math.max(a.left,b.left);const oy=Math.min(a.bottom,b.bottom)-Math.max(a.top,b.top);if(ox>1.5&&oy>1.5)res.push({k:fig.dataset.k,kind:'overlap',a:ts[i].textContent.slice(0,40),b:ts[j].textContent.slice(0,40),ox:Math.round(ox)})}}}return res};
</script>`;
const per = 300;
for (let p = 0; p * per < all.length; p++) {
  const figs = all.slice(p * per, (p + 1) * per).map(([k, s]) => `<figure data-k="${k.replace(/"/g, '&quot;')}">${s}</figure>`).join('\n');
  writeFileSync(join(out, `g${p}.html`), `<!doctype html><meta charset="utf-8"><style>figure{margin:8px 0}svg{display:block}</style>${figs}${AUDIT}`);
}
console.log(JSON.stringify({ drawings: all.length, pages: Math.ceil(all.length / per) }));

