// Text vs its smallest enclosing shape (rect / polygon / ellipse / path box): flag text that sticks out sideways.
const shapeAudit=(doc)=>{const res=[];for(const fig of doc.querySelectorAll('figure')){const shapes=[...fig.querySelectorAll('rect,polygon,ellipse,circle,path')].map(s=>({s,b:s.getBoundingClientRect()})).filter(x=>x.b.width>8&&x.b.height>8);const root=fig.querySelector('svg').getBoundingClientRect();
for(const t of fig.querySelectorAll('text')){if(!t.textContent.trim())continue;const a=t.getBoundingClientRect();const cx=(a.left+a.right)/2,cy=(a.top+a.bottom)/2;
const host=shapes.filter(x=>x.b.left<=cx&&cx<=x.b.right&&x.b.top<=cy&&cy<=x.b.bottom&&!(Math.abs(x.b.width-root.width)<2&&Math.abs(x.b.height-root.height)<2)).sort((p,q)=>p.b.width*p.b.height-q.b.width*q.b.height)[0];
if(!host)continue;const over=Math.max(host.b.left-a.left,a.right-host.b.right);if(over>2)res.push({k:fig.dataset.k,t:t.textContent.slice(0,40),over:Math.round(over),shape:host.s.tagName,w:Math.round(host.b.width)})}}return res};
const out=[];for(let p=0;p<7;p++){const f=document.createElement('iframe');f.style.cssText='width:2400px;height:600px';f.src='/ov/g'+p+'.html';document.body.appendChild(f);await new Promise(r=>f.onload=r);await new Promise(r=>setTimeout(r,300));out.push(...shapeAudit(f.contentDocument));f.remove()}
window.__shape=out;const by={};for(const r of out){const t=r.k.startsWith('case:')?'case':r.k.endsWith('#detail')?'detail':r.k.startsWith('NR:')?'nr':'overview';by[t]=(by[t]||0)+1}
({total:out.length,by,figs:new Set(out.map(r=>r.k)).size,sample:out.slice(0,30)})

