// One-off: add the edit mode to the config-to-document rows of the READMEs and FEATURES pages.
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
const root = process.argv[2];
const edits = [
  ['README.md', 'reviewed by `sap-critic`. Read-only. |', 'reviewed by `sap-critic`. Read-only on SAP; an in-page edit mode lets the consultant correct the notes and hand the file back for the next version. |'],
  ['README.ko.md', '`sap-critic`이 검토한 컨설턴트 노트. 읽기 전용. |', '`sap-critic`이 검토한 컨설턴트 노트. SAP에는 읽기 전용이며, 페이지 안 편집 모드로 컨설턴트가 노트를 고쳐 다음 버전에 반영할 수 있음. |'],
  ['README.ja.md', 'がレビューしたコンサルタントノート。読み取り専用。 |', 'がレビューしたコンサルタントノート。SAP には読み取り専用。ページ内の編集モードでコンサルタントがノートを直し、次のバージョンに引き継げる。 |'],
  ['README.de.md', 'geprüft von `sap-critic`. Nur lesend. |', 'geprüft von `sap-critic`. Im SAP-System nur lesend; im Bearbeitungsmodus der Seite korrigiert der Berater die Hinweise, die in die nächste Version übernommen werden. |'],
  ['docs/FEATURES.md', 'consultant notes reviewed by `sap-critic` |', 'consultant notes reviewed by `sap-critic`, in-page edit mode for the notes (`--import` carries edits into the next version) |'],
  ['docs/FEATURES.ko.md', '`sap-critic`이 검토한 컨설턴트 노트) |', '`sap-critic`이 검토한 컨설턴트 노트, 노트 편집 모드 — `--import`로 다음 버전에 반영) |'],
  ['docs/FEATURES.ja.md', '`sap-critic` がレビューしたコンサルタントノート) |', '`sap-critic` がレビューしたコンサルタントノート、ノートの編集モード — `--import` で次のバージョンへ) |'],
  ['docs/FEATURES.de.md', 'von `sap-critic` geprüfte Beraterhinweise |', 'von `sap-critic` geprüfte Beraterhinweise, Bearbeitungsmodus für die Hinweise (`--import` übernimmt sie in die nächste Version) |'],
];
for (const [f, a, b] of edits) {
  const p = join(root, f);
  const s = readFileSync(p, 'utf8');
  if (s.split(a).length !== 2) throw new Error(`${f}: anchor found ${s.split(a).length - 1} times`);
  writeFileSync(p, s.replace(a, () => b));
  console.log('ok', f);
}

