// One-off: apply the review fixes to the edit mode, the import merge and the lint.
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
const root = process.argv[2];
const patch = (file, pairs) => {
  const p = join(root, file);
  let s = readFileSync(p, 'utf8');
  for (const [a, b] of pairs) {
    if (s.split(a).length !== 2) throw new Error(`${file}: anchor found ${s.split(a).length - 1} times: ${a.slice(0, 70)}`);
    s = s.replace(a, () => b);
  }
  writeFileSync(p, s);
  console.log('ok', file);
};

patch('scripts/config/config-doc-editor.mjs', [
  // Edited notes embedded as null mean "back to the generated note".
  ["for(const [k,v] of Object.entries(CE.edits))D.notes[k]=keepSvg(v,D.notes[k]);",
   "for(const [k,v] of Object.entries(CE.edits))if(v)D.notes[k]=keepSvg(v,D.notes[k]);\n// Each note as the page opened it, to drop changes that were undone back to it.\nconst bare=n=>n?JSON.stringify({...n,edited:undefined}):null;const orig={};"],
  // Fields get their own attributes: data-ef (path) and data-a (activity), never the filter chips' data-f.
  [`' contenteditable="plaintext-only" spellcheck="false" data-ph="'+esc(EL.placeholder)+'" data-f="'+esc(path)+'"'`,
   `' contenteditable="plaintext-only" spellcheck="false" data-ph="'+esc(EL.placeholder)+'" data-a="'+esc(cur)+'" data-ef="'+esc(path)+'"'`],
  ["function change(id,fn){const before=D.notes[id]?JSON.stringify(D.notes[id]):null;fn();",
   "function change(id,fn){const before=D.notes[id]?JSON.stringify(D.notes[id]):null;if(!(id in orig))orig[id]=bare(D.notes[id]);fn();"],
  ["document.addEventListener('focusout',e=>{const el=e.target.closest&&e.target.closest('[data-f]');if(!el||!cur||!D.notes[cur])return;",
   "document.addEventListener('focusout',e=>{const el=EDIT&&e.target.closest&&e.target.closest('[contenteditable][data-ef]');const id=el&&el.dataset.a;if(!el||!id||!D.notes[id])return;"],
  ["const p=el.dataset.f;if((getAt(D.notes[cur],p)??'')===v)return;change(cur,()=>setAt(D.notes[cur],p,v))});",
   "const p=el.dataset.ef;if((getAt(D.notes[id],p)??'')===v)return;change(id,()=>setAt(D.notes[id],p,v))});"],
  ["document.addEventListener('keydown',e=>{const el=e.target.closest&&e.target.closest('[data-f]');",
   "document.addEventListener('keydown',e=>{const el=EDIT&&e.target.closest&&e.target.closest('[contenteditable][data-ef]');"],
  [`const f=document.querySelector('[data-f="purpose"]');`, `const f=document.querySelector('[data-ef="purpose"]');`],
  [`const f=document.querySelector('[data-f="'+p+'.'+(l.length-1)+'"]');`, `const f=document.querySelector('[data-ef="'+p+'.'+(l.length-1)+'"]');`],
  // Only notes that differ from how the page opened them are saved; a removed note is saved as null.
  ["const ids=[...touched];for(const id of ids){if(D.notes[id]){D.notes[id].edited={author,at};CE.edits[id]=D.notes[id]}else delete CE.edits[id]}",
   "const ids=[...touched].filter(id=>bare(D.notes[id])!==orig[id]);for(const id of ids){if(D.notes[id]){D.notes[id].edited={author,at};CE.edits[id]=D.notes[id]}else CE.edits[id]=null}"],
